--
-- Triggers `loans`
--
DELIMITER $$
CREATE TRIGGER `trg_loans_dates` BEFORE UPDATE ON `loans` FOR EACH ROW BEGIN
  IF OLD.status <> NEW.status THEN

    IF NEW.status = 'approved' THEN
      IF NEW.start_date IS NULL THEN
        SET NEW.start_date = CURDATE();
      END IF;
      IF NEW.approved_at IS NULL THEN
        SET NEW.approved_at = NOW();
      END IF;
      SET NEW.end_date = NULL;
    END IF;

    IF NEW.status = 'closed' THEN
      IF NEW.end_date IS NULL THEN
        SET NEW.end_date = CURDATE();
      END IF;
      IF NEW.closed_at IS NULL THEN
        SET NEW.closed_at = NOW();
      END IF;
    END IF;

    IF NEW.status = 'rejected' THEN
      IF NEW.start_date IS NOT NULL AND NEW.end_date IS NULL THEN
        SET NEW.end_date = CURDATE();
      END IF;
      IF NEW.rejected_at IS NULL THEN
        SET NEW.rejected_at = NOW();
      END IF;
    END IF;

    IF NEW.status = 'defaulted' THEN
      IF NEW.end_date IS NULL THEN
        SET NEW.end_date = CURDATE();
      END IF;
      IF NEW.defaulted_at IS NULL THEN
        SET NEW.defaulted_at = NOW();
      END IF;
    END IF;

  END IF;
END
$$
DELIMITER ;

