--
-- Triggers `transactions`
--
DELIMITER $$
CREATE TRIGGER `trg_tx_loan_status_check_ins` BEFORE INSERT ON `transactions` FOR EACH ROW BEGIN
  DECLARE lst ENUM('requested','approved','closed','rejected','defaulted');

  IF NEW.type IN ('loan_principal','loan_interest') THEN

    IF NEW.loan_id IS NULL THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT='Loan transaction requires loan_id.';
    END IF;

    SELECT status INTO lst
    FROM loans
    WHERE loan_id = NEW.loan_id
    LIMIT 1;

    IF lst IS NULL THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT='Loan not found.';
    END IF;

    IF lst <> 'approved' THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT='Loan must be approved to accept payments.';
    END IF;

  END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_tx_member_check_ins` BEFORE INSERT ON `transactions` FOR EACH ROW BEGIN
  DECLARE mflag TINYINT;

  IF NEW.type IN ('contribution','withdrawal') THEN
    IF NEW.user_id IS NULL THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT='Savings transaction requires user_id.';
    END IF;

    SELECT is_member INTO mflag
    FROM users
    WHERE id = NEW.user_id
    LIMIT 1;

    IF mflag IS NULL OR mflag = 0 THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT='User is not a member: cannot contribute or withdraw.';
    END IF;
  END IF;

  IF NEW.type = 'expense' THEN
    SET NEW.user_id = NULL;
  END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_tx_member_check_upd` BEFORE UPDATE ON `transactions` FOR EACH ROW BEGIN
  DECLARE mflag TINYINT;

  IF NEW.type IN ('contribution','withdrawal') THEN
    IF NEW.user_id IS NULL THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT='Savings transaction requires user_id.';
    END IF;

    SELECT is_member INTO mflag
    FROM users
    WHERE id = NEW.user_id
    LIMIT 1;

    IF mflag IS NULL OR mflag = 0 THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT='User is not a member: cannot contribute or withdraw.';
    END IF;
  END IF;

  IF NEW.type = 'expense' THEN
    SET NEW.user_id = NULL;
  END IF;

END
$$
DELIMITER ;

